interface Bar {
    func f(): String
}

struct Foo <: Bar {
    func <!CANNOT_WEAKEN_ACCESS_PRIVILEGE!>f<!>(): String {
        "A"
    }
}

open class A {
    public open func f(): Foo {
        return Foo()
    }
}

class B <: A {
    public override func <!RETURN_TYPE_INCOMPATIBLE!>f<!>(): Bar {
        return Foo()
    }
}

func f(): Foo {
    return Foo()
}

