    var v1: VArray<Int64, $3> = [1, 2, 3]
    unsafe { f1(inout <!INOUT_CAN_ONLY_USED_IN_CFUNC_CALLING!>v1<!>, 3) }
    if (1 == v1[0] && 3 == v1[1] && 5 == v1[2]) {
        return 0
    }
    return 1
}

